/** The mock drills — GET /api/v1/facility/drills (who may call: holders of facility.view or facility.drill.manage). */
export function listDrills(query?: { date_from?: string | null; date_to?: string | null; kind?: "Fire" | "Evacuation" | "CodeBlue" | "MassCasualty" | "Earthquake" | "BombThreat" | "ChemicalSpill" | "PowerFailure" | "InfantAbduction" | "Flood" | "Other" | null; department_id?: number | null; status?: "Draft" | "Final" | null }): Promise<DrillOut[]> {
  return api<DrillOut[]>("GET", withQuery(`/facility/drills`, query), undefined);
}

/** Report a mock drill — POST /api/v1/facility/drills (who may call: holders of facility.drill.manage). */
export function addDrill(body: DrillFieldsIn): Promise<DrillDetailOut> {
  return api<DrillDetailOut>("POST", `/facility/drills`, body, { idempotent: true });
}

/** Drill coverage by department and shift — GET /api/v1/facility/drills/coverage (who may call: holders of facility.view or facility.drill.manage). */
export function coverage(): Promise<DrillCoverageOut> {
  return api<DrillCoverageOut>("GET", `/facility/drills/coverage`, undefined);
}

/** One drill report — GET /api/v1/facility/drills/{drill_id} (who may call: holders of facility.view or facility.drill.manage). */
export function getDrill(drill_id: number): Promise<DrillDetailOut> {
  return api<DrillDetailOut>("GET", `/facility/drills/${drill_id}`, undefined);
}

/** Complete the draft report — PUT /api/v1/facility/drills/{drill_id} (who may call: holders of facility.drill.manage). */
export function updateDrill(drill_id: number, body: DrillUpdateIn): Promise<DrillDetailOut> {
  return api<DrillDetailOut>("PUT", `/facility/drills/${drill_id}`, body);
}

/** Sign the report — POST /api/v1/facility/drills/{drill_id}/finalize (who may call: holders of facility.drill.manage). */
export function finalizeDrill(drill_id: number): Promise<DrillDetailOut> {
  return api<DrillDetailOut>("POST", `/facility/drills/${drill_id}/finalize`, undefined, { idempotent: true });
}

/** Record an action the drill showed was needed — POST /api/v1/facility/drills/{drill_id}/actions (who may call: holders of facility.drill.manage). */
export function addDrillAction(drill_id: number, body: QualityActionIn): Promise<QualityActionOut> {
  return api<QualityActionOut>("POST", `/facility/drills/${drill_id}/actions`, body, { idempotent: true });
}

/** The drill report (PDF) — GET /api/v1/facility/drills/{drill_id}/pdf (who may call: holders of facility.view or facility.drill.manage). */
export function drillPdf(drill_id: number): Promise<unknown> {
  return api<unknown>("GET", `/facility/drills/${drill_id}/pdf`, undefined);
}

/** Pick a member of staff — GET /api/v1/facility/staff (who may call: holders of facility.compliance.manage or facility.equipment.manage or facility.maintenance.record or facility.drill.manage or personnel.training.record). */
export function staffFacility(query?: { q?: string | null; department_id?: number | null; limit?: number }): Promise<FacilityStaffOut[]> {
  return api<FacilityStaffOut[]>("GET", withQuery(`/facility/staff`, query), undefined);
}

/** Live bed matrix (counts per ward + optional bed list) — GET /api/v1/beds/matrix (who may call: holders of ipd.bed.view or cssd.operate or infection.control.manage or complaint.manage or incident.view or facility.drill.manage or roster.manage.all or facility.equipment.manage or pharmacy.storage.record). */
export function bedMatrix(query?: { include_beds?: boolean }): Promise<BedMatrixOut> {
  return api<BedMatrixOut>("GET", withQuery(`/beds/matrix`, query), undefined);
}
